'use client';
import * as React from 'react';
import { cn, domId, omit, useMergedRef, useIsoLayoutEffect } from '../../internal/cn';
import { useExit } from '../../internal/useExit';
import { Icon, type IconSource } from '../Icon/Icon';
import { asIcon } from '../Icon/asIcon';
import { Tooltip } from '../Tooltip/Tooltip';
import { TruncatedText } from '../TruncatedText/TruncatedText';
import { config } from '../../internal/config';
import { Menu, MenuItem, MenuSub } from '../Menu/Menu';
import { named } from '../../internal/component';
import { activeIn } from '../../internal/root';
import { flattenChildren } from '../../internal/children';
import { useSettings } from '../../internal/provider';
import type { OpenChangeDetails } from '../../internal/openChange';
import * as icons from '../../material/builtin';
import { useControllable } from '../../internal/controllable';
import { hideUntilFound } from '../../internal/untilFound';

export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  /** SidebarSections, or SidebarItems directly. */
  children?: React.ReactNode | undefined;
  /** Above the items: a logo, a workspace switcher. */
  header?: React.ReactNode | undefined;
  /** Pinned to the bottom: settings, the signed-in user. */
  footer?: React.ReactNode | undefined;
  /** Narrows it to icons only (64px). Labels show as tooltips, and groups open their items in a menu. Default: false. */
  collapsed?: boolean | undefined;
  /** The nav's accessible name. Default: "Main". */
  'aria-label'?: string | undefined;
}

export interface SidebarSectionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  /** A small heading over the section's items. Hidden when the sidebar is collapsed. */
  title?: React.ReactNode | undefined;
  /** SidebarItems. */
  children?: React.ReactNode | undefined;
}

/** SidebarItem's own props, beside those of the element it renders. */
export interface SidebarItemOwnProps {
  /** The item's text. */
  label: React.ReactNode;
  /** An icon before the label: a Material Symbols or custom name, or an element. Top-level items need one to show when collapsed. */
  icon?: IconSource | undefined;
  /** The current page: shaded, with a bar in the primary color and aria-current="page". Default: false. */
  current?: boolean | undefined;
  /** Something at the end, such as a count Badge. Collapsed, a dot on the icon shows there is one, and screen readers still read it. */
  badge?: React.ReactNode | undefined;
  /** Nested SidebarItems: the item becomes a button that shows and hides them. */
  children?: React.ReactNode | undefined;
  /** With children: open at first. Default: open when one of them is active. */
  defaultOpen?: boolean | undefined;
  /** With children: whether the group is open, controlled. Pair it with onOpenChange. */
  open?: boolean | undefined;
  /** With children: called when the group's button asks to open or close it, with why: { reason: 'trigger' }. */
  onOpenChange?: ((open: boolean, details: OpenChangeDetails) => void) | undefined;
}

/** SidebarItem's props: its own, `as`, and the props of the element `as` names (an <a>'s by default), so
 *  <SidebarItem as={RouterLink} to="/inbox"> takes RouterLink's `to`. With children it renders a button, which
 *  gets those attributes and handlers too. */
export type SidebarItemProps<C extends React.ElementType = 'a'> = SidebarItemOwnProps & {
  /** What renders the link: your router's link component. Default: the link set with configure({ link }), else 'a'. */
  as?: C | undefined;
} & Omit<React.ComponentPropsWithoutRef<C>, keyof SidebarItemOwnProps | 'as'>;

// Inside, the item is a link or a button, so its attributes and handlers are typed for HTMLElement, which both are.
type ItemProps = SidebarItemOwnProps & { as?: React.ElementType } & Omit<React.AnchorHTMLAttributes<HTMLElement>, keyof SidebarItemOwnProps>;

const SidebarContext = /* @__PURE__ */ React.createContext<{ collapsed: boolean; depth: number }>({ collapsed: false, depth: 0 });

function isSection(c: React.ReactNode): boolean {
  return React.isValidElement(c) && c.type === SidebarSection;
}

function SidebarRender({ ref, ...props }: SidebarProps & React.RefAttributes<HTMLElement>) {
  const sds = useSettings();
  const rest = omit(props, { header: 1, footer: 1, collapsed: 1, className: 1, children: 1, 'aria-label': 1 });
  const collapsed = !!props.collapsed;
  // The column's width changes once, not on every frame (EA1): expanding widens it at the start, collapsing narrows
  // it at the end, and in between a clip-path (with a line for the edge) slides, which the compositor runs alone.
  // shown is the layout (rail or full); slide is the clip: "rail" or "full" while it moves, "" at rest.
  const [shown, setShownNow] = React.useState(collapsed);
  const [slide, setSlide] = React.useState<'' | 'rail' | 'full'>('');
  const nav = React.useRef<HTMLElement | null>(null);
  // Switching between the rail and the full list re-renders the items (a group's nested list becomes a Menu, a
  // link gets its tooltip), so the focused one goes away and focus would fall to <body>. The top-level item it was
  // in is kept, and focus goes to that item's link or button once the switch has rendered (GM3).
  const keep = React.useRef<Element | null>(null);
  const setShown = React.useCallback((v: boolean) => {
    const n = nav.current, a = activeIn(n);   // its own root's focus, in a shadow root too (GR90)
    let li = n && a && n.contains(a) ? a.closest('.srp-sidebar__li') : null;
    for (let up = li && li.parentElement ? li.parentElement.closest('.srp-sidebar__li') : null; up && n && n.contains(up); up = up.parentElement ? up.parentElement.closest('.srp-sidebar__li') : null) li = up;
    keep.current = li;
    setShownNow(v);
  }, []);
  useIsoLayoutEffect(() => {
    const li = keep.current, n = nav.current;
    keep.current = null;
    if (li && li.isConnected && n && !n.contains(activeIn(n))) { const to = li.querySelector<HTMLElement>('a[href], button'); if (to) to.focus(); }
  }, [shown]);
  const want = React.useRef(collapsed);
  const timer = React.useRef<{ raf?: number; end?: ReturnType<typeof setTimeout> }>({});
  const settle = React.useCallback(() => {
    clearTimeout(timer.current.end);
    if (want.current) setShown(true);
    setSlide('');
  }, [setShown]);
  useIsoLayoutEffect(() => {
    if (want.current === collapsed) return;
    want.current = collapsed;
    const n = nav.current, t = timer.current;
    cancelAnimationFrame(t.raf as number);
    clearTimeout(t.end);
    const ms = n ? Math.max(...getComputedStyle(n).transitionDuration.split(',').map((d) => parseFloat(d) * (/ms/.test(d) ? 1 : 1000))) : 0;
    if (!ms) { setShown(collapsed); setSlide(''); return; }   // no motion (reduced motion): snap
    // From rest, show the clip's start for a frame before it moves; mid-way, turn back from where it is.
    const from = slide === '' ? (collapsed ? 'full' : 'rail') : null;
    if (!collapsed) setShown(false);
    const go = () => { setSlide(collapsed ? 'rail' : 'full'); t.end = setTimeout(settle, ms + 100); };
    if (from) { setSlide(from); t.raf = requestAnimationFrame(() => { t.raf = requestAnimationFrame(go); }); } else go();
  }, [collapsed]);
  React.useEffect(() => () => { cancelAnimationFrame(timer.current.raf as number); clearTimeout(timer.current.end); }, []);
  const onEnd = (e: React.TransitionEvent<HTMLElement>) => { if (e.target === e.currentTarget && e.propertyName === 'clip-path' && (slide === 'rail') === want.current) settle(); };
  // runs of loose items get their own list
  const body: React.ReactNode[] = [];
  let run: React.ReactNode[] = [];
  const flush = () => { if (run.length) { body.push(<ul key={'l' + body.length} className="srp-sidebar__list">{run}</ul>); run = []; } };
  flattenChildren(props.children).forEach((c) => { if (isSection(c)) { flush(); body.push(c); } else run.push(c); });
  flush();
  const mergedRef = useMergedRef(ref, (n) => { nav.current = n; });
  return (
    <SidebarContext.Provider value={{ collapsed: shown, depth: 0 }}>
      <nav {...rest} aria-label={props['aria-label'] || sds.labels.mainNavigation} ref={mergedRef} data-component="sidebar" data-collapsed={shown ? '' : undefined}
        data-slide={slide || undefined} onTransitionEnd={(e) => { onEnd(e); if (props.onTransitionEnd) props.onTransitionEnd(e); }}
        className={cn('srp-sidebar', shown && 'srp-sidebar--collapsed', props.className)}>
        {props.header != null ? <div className="srp-sidebar__header">{props.header}</div> : null}
        <div className="srp-sidebar__body">{body}</div>
        {props.footer != null ? <div className="srp-sidebar__footer">{props.footer}</div> : null}
      </nav>
    </SidebarContext.Provider>
  );
}

/* Sidebar: a vertical <nav> for an app's main pages: an optional header, sections of items (icons, labels,
   badges, nested groups), and a footer pinned to the bottom. collapsed narrows it to an icon rail. It takes
   its parent's height; className and every other prop go to the <nav>. */
/** A vertical nav for an app's pages: sections of items with icons, badges and nested groups; collapses to an icon rail. */
export const Sidebar = /* @__PURE__ */ named('Sidebar', SidebarRender);

function SidebarSectionRender({ ref, ...props }: SidebarSectionProps & React.RefAttributes<HTMLDivElement>) {
  const rest = omit(props, { title: 1, className: 1, children: 1 });
  const id = domId('srp-sbs', React.useId());
  const titled = props.title != null && props.title !== false && props.title !== '';
  return (
    <div {...rest} ref={ref} className={cn('srp-sidebar__section', props.className)}>
      {titled ? <div id={id} className="srp-sidebar__section-title">{props.title}</div> : null}
      <ul className="srp-sidebar__list" aria-labelledby={titled ? id : undefined}>{props.children}</ul>
    </div>
  );
}

/** A group of items in a Sidebar, with an optional small heading. */
export const SidebarSection = /* @__PURE__ */ named('SidebarSection', SidebarSectionRender);

const ITEM_OWN = { label: 1, icon: 1, current: 1, badge: 1, children: 1, defaultOpen: 1, open: 1, onOpenChange: 1, as: 1, className: 1 } as const;
type ItemElement = React.ReactElement<ItemProps>;
const itemsOf = (children: React.ReactNode) => flattenChildren(children).filter(React.isValidElement) as ItemElement[];
/** The item is the current page, or one of its items is, at any depth: a group opens and shows active for a grandchild too. */
const activeWithin = (k: ItemElement): boolean => !!k.props.current || itemsOf(k.props.children).some(activeWithin);

/* The rail's Menu for a group: each item keeps its link component (as), its other link attributes and the current
   page, and a nested group is a submenu of its own items, so they can still be reached (L8E68). */
function railItems(kids: ItemElement[]): React.ReactNode {
  return kids.map((k, i) => {
    const key = k.key != null ? k.key : i, inner = itemsOf(k.props.children);
    const common = { icon: k.props.icon, 'aria-current': activeWithin(k) ? ('page' as const) : undefined, className: cn('srp-sidebar__menu-item', k.props.className) };
    if (inner.length) return <MenuSub key={key} {...common} label={k.props.label}>{railItems(inner)}</MenuSub>;
    return <MenuItem key={key} {...omit(k.props, ITEM_OWN) as object} onClick={undefined} as={k.props.as} {...common}
      onSelect={k.props.onClick as ((e: React.SyntheticEvent) => void) | undefined}>{k.props.label}</MenuItem>;
  });
}

function SidebarItemBaseRender({ ref, ...props }: ItemProps & React.RefAttributes<HTMLElement>) {
  const ctx = React.useContext(SidebarContext);
  const rest = omit(props, ITEM_OWN);
  const kids = itemsOf(props.children);
  const group = kids.length > 0;
  const childActive = kids.some(activeWithin);
  const [held, setOwn, controlled] = useControllable(props.open, props.defaultOpen != null ? !!props.defaultOpen : childActive, 'SidebarItem', 'open');
  // The page moving to one of its items (a link elsewhere, the browser's Back) opens it too, as arriving there does,
  // so the current page isn't hidden in a closed group (L8E108). defaultOpen set, or open, leaves that to you.
  const [wasActive, setWasActive] = React.useState(childActive);
  if (wasActive !== childActive) { setWasActive(childActive); if (childActive && !held && props.defaultOpen == null && !controlled) setOwn(true); }
  const open = !!held;
  const toggle = () => {
    if (!controlled) setOwn(!open);
    if (props.onOpenChange) props.onOpenChange(!open, { reason: 'trigger' });
  };
  const listId = domId('srp-sbi', React.useId());
  // A group's nested list unfolds and folds as Accordion's panel does (GM4): it stays (inert) while it folds away.
  // From the keyboard it opens at once, as it closes at once (KW1).
  const nested = React.useRef<HTMLUListElement | null>(null);
  const exit = useExit(open, nested);
  // A closed group's list is hidden="until-found", as Accordion's panels are: hidden from everyone, but find-in-page
  // still searches it, and a match fires beforematch, which opens the group (search-hidden-content). The server's
  // HTML has plain hidden (React can only write hidden=""); it becomes until-found here, once it's done folding.
  const toggleRef = React.useRef(toggle);
  React.useInsertionEffect(function () { toggleRef.current = toggle; });   // every render: the latest toggle, for beforematch
  const shut = !open && !exit.leaving;
  React.useEffect(function () {
    const el = nested.current;
    if (!el || !shut) return;
    hideUntilFound(el);
    const onMatch = function () { toggleRef.current(); };
    el.addEventListener('beforematch', onMatch);
    return function () { el.removeEventListener('beforematch', onMatch); };
  }, [shut]);
  const rail = ctx.collapsed && ctx.depth === 0;
  // In the rail the badge is hidden on screen, like the label, and a dot on the icon says there is one.
  const dot = rail && props.badge != null && props.badge !== false;
  // There the tooltip is the item's name (aria-labelledby replaces its text), so the badge is read as its
  // description: "Inbox", then "4".
  const badgeId = listId + '-badge';
  const described = !!rest['aria-describedby'];
  if (dot) rest['aria-describedby'] = cn(rest['aria-describedby'], badgeId);
  // A text label cut with an ellipsis shows in full on hover and on the item's keyboard focus (TruncatedText), not
  // only as a title the keyboard never sees. Not in the rail, where the tooltip already names it, with a title of its
  // own, or in a Tooltip (its aria-describedby, given before the rail's badge adds one), which shows the cut label itself.
  const text = typeof props.label === 'string' || typeof props.label === 'number' ? String(props.label) : '';
  const tipOk = !!text && !rail && rest.title == null && !described;
  const inner = (chevron: boolean) => <>
    {props.icon ? <span className="srp-sidebar__icon">{asIcon(props.icon)}{dot ? <span className="srp-sidebar__dot" aria-hidden="true" /> : null}</span> : null}
    <span className="srp-sidebar__label">{tipOk ? <TruncatedText>{text}</TruncatedText> : props.label}</span>
    {props.badge != null ? <span className="srp-sidebar__badge" id={dot ? badgeId : undefined}>{props.badge}</span> : null}
    {chevron && !rail ? <Icon icon={icons.ExpandMore} className="srp-sidebar__chevron" /> : null}
  </>;
  // An item with children is a button, not a link: its other attributes and handlers go to the button. Its events and
  // ref are typed for HTMLElement, which both the link and the button are.
  const btnProps = omit(rest, { href: 1, target: 1, rel: 1, download: 1, hrefLang: 1, ping: 1, referrerPolicy: 1, type: 1, onClick: 1 });
  const cls = cn('srp-sidebar__item', ctx.depth > 0 && 'srp-sidebar__item--nested', (props.current || (group && childActive)) && 'srp-sidebar__item--active', props.className);
  const here = props.current || (group && childActive) ? '' : undefined;   // data-current: this page, or a group holding it

  if (group && rail) {
    return (
      <li className="srp-sidebar__li">
        <Menu placement="right-start" trigger={
          props.label != null && props.label !== false && props.label !== ''
            ? <Tooltip content={props.label} placement="right" role="label"><button type="button" {...btnProps} ref={ref as React.Ref<HTMLButtonElement>} className={cls} data-current={here}>{inner(false)}</button></Tooltip>
            : <button type="button" {...btnProps} ref={ref as React.Ref<HTMLButtonElement>} className={cls} data-current={here}>{inner(false)}</button>
        }>
          {railItems(kids)}
        </Menu>
      </li>
    );
  }
  if (group) {
    return (
      <li className="srp-sidebar__li" data-state={open ? 'open' : 'closed'}>
        <button type="button" {...btnProps} ref={ref as React.Ref<HTMLButtonElement>} className={cls} data-current={here} aria-expanded={open} aria-controls={listId} onClick={(e) => { if (props.onClick) props.onClick(e); toggle(); }}>{inner(true)}</button>
        <SidebarContext.Provider value={{ collapsed: ctx.collapsed, depth: ctx.depth + 1 }}>
          <ul ref={nested} id={listId} className="srp-sidebar__list srp-sidebar__list--nested" hidden={shut} inert={(!open && exit.leaving) || undefined} data-instant={exit.instant || undefined}>{kids}</ul>
        </SidebarContext.Provider>
      </li>
    );
  }
  const Tag = props.as || config.link;
  const link = <Tag {...rest} ref={ref} className={cls} data-current={here} aria-current={props.current ? 'page' : undefined}>{inner(false)}</Tag>;
  return (
    <li className="srp-sidebar__li">
      {rail && props.label != null && props.label !== false && props.label !== '' ? <Tooltip content={props.label} placement="right" role="label">{link}</Tooltip> : link}
    </li>
  );
}

/* SidebarItem: a link (icon, label, badge), or with nested items a button with aria-expanded that shows and
   hides them. Collapsed: only the icon, with the label as a tooltip; a group opens its items in a Menu. The ref
   goes to the link or the group's button. */
/** An item in a Sidebar: a link, or a group of nested items. */
const SidebarItemBase = /* @__PURE__ */ named('SidebarItem', SidebarItemBaseRender);

/** An item in a Sidebar: a link, or a group of nested items. `as` renders your router's link, typed with its props. */
export const SidebarItem = SidebarItemBase as {
  <C extends React.ElementType = 'a'>(props: SidebarItemProps<C> & React.RefAttributes<HTMLElement>): React.ReactElement | null;
  displayName?: string | undefined;
};
